SELECT e.id, e.employee_no, e.name, e.phone, e.department_id, e.position_id,
       e.status, e.hire_date, e.leave_date
FROM employee e
WHERE 1 = 1

    AND (e.employee_no LIKE CONCAT('%', #{keyword}, '%') OR e.name LIKE CONCAT('%', #{keyword}, '%'))

AND e.status = #{status}
AND e.department_id = #{departmentId}

ORDER BY e.created_at DESC, e.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM employee e
WHERE 1 = 1

    AND (e.employee_no LIKE CONCAT('%', #{keyword}, '%') OR e.name LIKE CONCAT('%', #{keyword}, '%'))

AND e.status = #{status}
AND e.department_id = #{departmentId}

SELECT id, employee_no, name, phone, department_id, position_id, status, hire_date, leave_date
FROM employee
WHERE id = #{id}

    AND 1 = 1
    AND department_id = #{departmentId}
    AND id = #{employeeId}
    AND 1 = 0

LIMIT 1

